def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v not in (0, 5)]
    rows = [r for r,row in enumerate(grid) if any(x == 5 for x in row)]
    cols = [c for c,x in enumerate(grid[rows[0]]) if x == 5]
    r0,rmax=min(rows),max(rows); c0,cmax=min(cols),max(cols)
    rm=(r0+rmax)//2; cm=(c0+cmax)//2
    diagonal = {};
    for r,c,v in markers:
        same = ((r < rm) == (c < cm))
        diagonal[same] = v
    for r in range(r0+1,rmax):
        for c in range(c0+1,cmax):
            out[r][c] = diagonal[(r <= rm) == (c <= cm)]
    return out

